// Sprite coordinates refer to the actual original 1200 × 900 illustrations,
// normalized to the puzzle's 800 × 600 coordinate system. No structures are redrawn.
// Closed paths include only the selected original pixels; patches localize clean plates.
const k=(at,x=0,y=0,rotate=0,opacity=1,scale=1)=>({at,x,y,rotate,opacity,scale});
const circle=(x,y,r)=>`M ${x-r} ${y} a ${r} ${r} 0 1 0 ${r*2} 0 a ${r} ${r} 0 1 0 ${-r*2} 0 Z`;
const ellipse=(x,y,rx,ry)=>`M ${x-rx} ${y} a ${rx} ${ry} 0 1 0 ${rx*2} 0 a ${rx} ${ry} 0 1 0 ${-rx*2} 0 Z`;
const polygon=points=>`M ${points.map(([x,y])=>`${+(x/1.5).toFixed(2)} ${+(y/1.5).toFixed(2)}`).join(' L ')} Z`;
const outline=(points,center,expansion=1.025)=>({clip:polygon(points),patch:polygon(points.map(([x,y])=>[center[0]+(x-center[0])*expansion,center[1]+(y-center[1])*expansion])),center:center.map(n=>n/1.5)});
const bead=(id,x,y,r,keyframes)=>({id,clip:circle(x,y,r),patch:circle(x,y,r+3),center:[x,y],keyframes});
const drift=(x,y,rotate=0)=>[k(0),k(.25,x,y,rotate),k(.55,-x*.65,-y*.5,-rotate*.6),k(.8,x*.35,-y*.25,rotate*.2),k(1)];
const transport=(x,y,{delay=.12,finish=.7,rotate=0}={})=>[k(0),k(delay),k(finish,x,y,rotate),k(finish+.06,x,y,rotate,0),k(.94,0,0,0,0),k(1)];
